using System.Xml.Linq;
using OpenPEData.Runtime;

namespace OpenPEData.Tests;

/// <summary>Nodes of an OPC UA server interface (sample 081: nodeset import, local data generated by TIA) against the Openness
/// export of the interface: NodeId, BrowseName, DisplayName, DataType, AccessLevel and the si:VariableMapping of every node.</summary>
public static class PlcOpcUaNodeTests
{
    [Test]
    public static void ServerInterfaceNodesAgainstExport()
    {
        var c = new Check("081 OPC UA server interface nodes = Openness export");
        var truth = XElement.Load(Path.Combine(Program.Root, "samples", "081_plc_opcua_nodes_truth", "SI_Test.xml"));
        using var p = TiaProject.Open(Path.Combine(Program.Root, "samples", "081_plc_opcua_nodes.zap21"));
        var proj = (PyDict)((PyDict)p.Raw(TiaContent.Structure, default)!)["project"]!;
        var si = ((List<object?>)proj["plcOpcUaInterfaces"]!).Cast<PyDict>().FirstOrDefault(x => (string?)x["name"] == "SI_Test");
        c.True(si is not null, "interface SI_Test");
        var nodes = ((si?.Get("nodes") as List<object?>) ?? []).Cast<PyDict>().ToDictionary(n => (string)n["nodeId"]!);
        var count = 0;
        foreach (var n in truth.Elements().Where(e => e.Name.LocalName is "UAObject" or "UAVariable"))
        {
            var id = (string)n.Attribute("NodeId")!;
            count++;
            if (!nodes.TryGetValue(id, out var got))
            {
                c.Fail($"{id}: missing");
                continue;
            }
            c.Eq(n.Name.LocalName[2..], got["nodeClass"], id + " class");
            c.Eq((string?)n.Attribute("BrowseName"), got["browseName"], id + " BrowseName");
            c.Eq(n.Elements().FirstOrDefault(e => e.Name.LocalName == "DisplayName")?.Value, got["displayName"], id + " DisplayName");
            c.Eq((string?)n.Attribute("DataType"), got["dataType"], id + " DataType");
            c.Eq((string?)n.Attribute("AccessLevel"), got["accessLevel"], id + " AccessLevel");
            c.Eq(n.Descendants().FirstOrDefault(e => e.Name.LocalName == "VariableMapping")?.Value, got["mapping"], id + " mapping");
        }
        c.Eq(3, count, "nodes compared");
        c.Done();
    }

    /// <summary>Sample 082 (081 plus reference namespace RN_Types from a nodeset with an object type): interface kinds against
    /// Openness opcUaInterfaceList, nodes of the reference namespace against its export.</summary>
    [Test]
    public static void ReferenceNamespaceAgainstExport()
    {
        var c = new Check("082 OPC UA reference namespace = Openness");
        var dir = Path.Combine(Program.Root, "samples", "082_plc_opcua_refns_truth");
        var truth = XElement.Load(Path.Combine(dir, "RN_Types.xml"));
        var list = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(Path.Combine(dir, "opcUaInterfaceList.json")))!["items"]!.AsArray();
        using var p = TiaProject.Open(Path.Combine(Program.Root, "samples", "082_plc_opcua_refns.zap21"));
        var proj = (PyDict)((PyDict)p.Raw(TiaContent.Structure, default)!)["project"]!;
        var ifs = ((List<object?>)proj["plcOpcUaInterfaces"]!).Cast<PyDict>().ToDictionary(x => (string)x["name"]!);
        foreach (var it in list)
        {
            var name = it!["name"]!.GetValue<string>();
            c.Eq(it["interfaceKind"]!.GetValue<string>(), ifs.GetValueOrDefault(name)?.Get("interfaceKind"), name + " kind");
            c.Eq(it["enabled"]!.GetValue<bool>(), ifs.GetValueOrDefault(name)?.Get("enabled"), name + " enabled");
        }
        var nodes = ((ifs.GetValueOrDefault("RN_Types")?.Get("nodes") as List<object?>) ?? []).Cast<PyDict>().ToDictionary(n => (string)n["nodeId"]!);
        var count = 0;
        foreach (var n in truth.Elements().Where(e => e.Name.LocalName.StartsWith("UA", StringComparison.Ordinal)))
        {
            var id = (string)n.Attribute("NodeId")!;
            count++;
            c.True(nodes.TryGetValue(id, out var got), id + " present");
            c.Eq(n.Name.LocalName[2..], got?["nodeClass"], id + " class");
            c.Eq((string?)n.Attribute("BrowseName"), got?["browseName"], id + " BrowseName");
        }
        c.Eq(2, count, "nodes compared");
        c.Done();
    }
}
